if(!goal.lessons[n.id]){b.append(E('p','Preparando solo esta microlección…'));await task('Preparando una explicación breve…',async()=>{let parent=s.stack[s.stack.length-1],p=goal.nodes.find(x=>x.id===parent);goal.lessons[n.id]=await api('/api/lesson',{goal:goal.goal,name:n.name,parent:p?.name||goal.goal});save();render()});return}
let l=goal.lessons[n.id];
if(s.mode==='TEACH'){b.append(E('h3','Una idea a la vez'),E('p',l.explanation),E('p','Ejemplo'),E('pre',l.example),E('p',`Error habitual: ${l.common_error}`));b.append(B('Ahora lo intento',()=>{s.mode='COMPREHENSION';state(goal,n.id).level=Math.max(1,state(goal,n.id).level);save();render()}));return}
let phase=s.mode,question=phase==='COMPREHENSION'?l.check:phase==='GUIDED'?l.guided:(phase==='INDEPENDENT'||phase==='CHALLENGE')?l.independent:l.integration,role=phase==='COMPREHENSION'?'comprehension_check':phase==='GUIDED'?'guided_practice':(phase==='INDEPENDENT'||phase==='CHALLENGE')?'independent_practice':'integration';
