async function reviewView(box,goal,n){let r=goal.reviews.find(x=>x.id===n.id);if(!r){goal.session.mode='DIAGNOSTIC';render();return}if(!r.question){try{let d=await api('/api/review',{goal:goal.goal,concept:n.name,level:r.step,previous:r.history.slice(-3).map(x=>x.prompt).join('; ')});r.question=d.question;save()}catch(e){note(e.message+' Reutilizaré un caso guardado.',true);r.question=goal.lessons[n.id]?.independent||n.probe;save()}}renderQuestion(box,r.question,n.id,'REVIEW','spaced_review');box.append(B('No recuerdo; volvamos a aprenderlo',()=>{r.due=Date.now()+DAY;r.step=0;r.question=null;save();startTeach(goal,n.id)},true))}


// Context stack: the top context alone is evaluated. Parents remain paused.
function repairCanRequestHint(stage){return ['CHECK','GUIDED','INDEPENDENT'].includes(stage)}
function registerRepairHint(episode,stage,source='requested'){if(!episode||episode.closed_at||!repairCanRequestHint(stage))return false;episode.current_help_used=Math.max(0,Number(episode.current_help_used)||0)+1;episode.hint_history=Array.isArray(episode.hint_history)?episode.hint_history:[];episode.hint_history.push({stage,source,at:Date.now()});return true}
