function topContext(goal){let s=contextStack(goal);return s[s.length-1]}
function canPushContext(goal,ctx){let stack=contextStack(goal);if(stack.length>=REPAIR_LIMITS.max_depth)return {ok:false,reason:'MAX_DEPTH'};if(ctx?.episode_id&&ctx?.gap_id&&stack.some(x=>x.episode_id===ctx.episode_id&&x.gap_id===ctx.gap_id))return {ok:false,reason:'DUPLICATE_GAP'};return {ok:true,reason:null}}
