 box.append(E('p',`Episodio ${episode.episode_id} · ${episode.status}`),E('p',`Problema padre: ${episode.parent_question?.prompt||'sin texto'}`));if(episode.selected_gap)box.append(E('p',`Laguna prioritaria: ${episode.selected_gap.concept} (${episode.selected_gap.status})`));box.append(E('h3',labels[current.phase]||current.phase),E('p',current.question.prompt));
